insert into `slides` values ('2','轮播图2','内容2','/article/details?article=2','/api/upload/1565515779821010944.jpg','850','2023-03-06 14:58:06.0','2023-03-06 14:58:06.0');
insert into `slides` values ('3','轮播图3','内容3','/article/details?article=3','/api/upload/1565515480062492673.jpg','682','2023-03-06 14:58:06.0','2023-03-06 14:58:06.0');
insert into `article` values ('1','女人练肌肉比男人难','健身','176','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>一直觉得健身对女生不太友好，整个社会对健身的女生不太友好。</p><p>&nbsp;</p><p>换一种说法就是，能坚持健身的女生都不太容易，坚持练肌肉的女生都不太容易！</p><p>&nbsp;</p><p><strong style="background-color: transparent;">特别是在中国…女人练肌肉比男人难。</strong></p><p>&nbsp;</p><p>女生去健身房不容易体现在方方面面。</p><p>&nbsp;</p><p>最主要不容易就是是部分中国男性的恶毒眼光。</p><p>&nbsp;</p><p>如果我眼睛不瞎的话，现在应该是 2021 年，却依然还有男生说：</p><p>&nbsp;</p><p>“去健身房的，都不是好女人。”</p><p>&nbsp;</p><p>好家伙，我不睁眼还以为这位哥活在清朝呢，先把您头上的辫子剪一剪行吗？！</p><p>&nbsp;</p><p>这位哥的观点是：“正经女人三不去：一不去酒店，二不去洗浴按摩，三不去健身房。”</p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center">&nbsp;</p><p>好家伙，我直呼好家伙，而这条视频，居然能高达几十万点赞，评论里也有无数男性跟着附和…</p><p>&nbsp;</p><p>总有一天我会死，那肯定是被这群人气死的。</p><p>&nbsp;</p><p>不光有无数人对去健身房的女生带着有色眼镜，还和女生的穿着打扮过不去。</p><p>&nbsp;</p><p>穿少了就说“骚”，穿多了就说“压根不是去健身的”，穿紧身的就说“去勾引人的”。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">健身难！健身房的女人难！女人练肌肉比男人更难！</strong></p><p>&nbsp;</p><p>好不容易现在国外流行起了“女性专用健身房”。</p><p>&nbsp;</p><p>到了国内同样引得无数女性的呼声，却不少男生依旧不满。</p><p>&nbsp;</p><p>“这是性别歧视！”</p><p>“这健身房肯定不长久，女生压根就不是去健身房健身的！”</p><p>“女生都去那里锻炼了，我看谁？”</p><p>&nbsp;</p><p>当女生在中国练出了肌肉</p><p>&nbsp;</p><p>尽管健身很难，同样也有很多女生坚持了下去，并且练出了傲人的身材。</p><p>&nbsp;</p><p>但就是这样的身材，又能引起一系列来自男人的硬杠：</p><p>&nbsp;</p><p>“女人这样的健身身材，没几个男人会喜欢的。”</p><p>&nbsp;</p><p>不管你喜不喜欢，人家也绝看不上你…</p><p>&nbsp;</p><p><strong style="background-color: transparent;">“难看、可怕、男人婆、女汉子”，基本上每一个练出肌肉的女生都会受到这样的攻击。</strong></p><p>&nbsp;</p><p>没有难听的，只有更难听的：</p><p>&nbsp;</p><p>“女人不打针吃药，别想练出这种肌肉。”</p><p>“她这样后期是不是会长胡子，然后声音变粗？”</p><p>“女人就该柔美，别急着反驳，有几个男的愿意娶这样的女人？”</p><p>“难生育。”</p><p>&nbsp;</p><p>这种问题真的把人都看呕了，女生健身难生育，那男生健身岂不是就要yangwei？</p><p>&nbsp;</p><p>每次看到这样的无脑评论，句句充满了幽怨的气息，真 · 普通又自信。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">能练成这样的女生，真的丝毫不会在意你的评价…</strong></p><p>&nbsp;</p><p><strong style="background-color: transparent;">女人练肌肉比男人本来就难！</strong></p><p>&nbsp;</p><p>从增肌的角度上来说，女生增肌本身就比男生要困难得多。</p><p>&nbsp;</p><p>男生能很快练出饱满的肌肉，是因为体内的雄性激素含量多，是增肌的关键。</p><p>&nbsp;</p><p>而女生体内雄性激素的含量非常少，大约是男生的 1/16 。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">所以，女生要想练出肌肉身材，在运动上花费的时间只会比男生要多。</strong></p><p>&nbsp;</p><p>并且在健身、饮食、生活上更需要非常注重细节。</p><p>&nbsp;</p><p>作息规律、饮食健康，这都是一个大前提。</p><p>&nbsp;</p><p>女生练出肌肉非常难，但拥有肌肉却好处非常多。</p><p>&nbsp;</p><p>有肌肉的女生身材更好，皮肤更紧致，身体更有活力，对生活充满了激情和自信。</p><p>&nbsp;</p><p>有肌肉的女生不怕岁月的洗礼，哪怕经过十年二十年，她们的身体状态也比同龄人更加年轻。</p><p>&nbsp;</p><p>想必到时候那些男生就会哐哐哐打脸，打脸自己年轻时的无知。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">女生练肌肉真的很难，不管是心理上、身理上，还是审美上、社会舆论上。</strong></p><p>&nbsp;</p><p>女生健身、练肌肉，希望所有人都不要对她们产生过分的误解和压力。</p><p>&nbsp;</p><p>这样的女生真的很棒！</p><p>&nbsp;</p><p>最嘲讽的是，很多人看到国外健身女神是这样的反应：</p><p>&nbsp;</p><p>“真好看！练的真好！真性感！这就是女神！”</p><p>&nbsp;</p><p>看到中国女生练出肌肉之后：</p><p>&nbsp;</p><p>“恶心、想吐，练成这样图什么？”</p>','/api/upload/1601838017780121600.jpg',null);
insert into `article` values ('2','【提醒】运动健身后，这几件事绝对不能碰！','健身','714','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center"><img src="data:image/png;base64,"></p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p>','/api/upload/1565538591621251073.jpg',null);
insert into `article` values ('3','弗兰克赞恩击败过施瓦辛格的选手','健身','246','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>天赋平平的你我也许永远也没机会站在奥赛的舞台之上，但骨子里的热爱，让我们在健美的道路上奋力前行。虽然我们不能成为奥林匹亚先生，但可以借鉴他们的某些训练方法——今天就一起来看看比例之王“弗兰克赞恩”的训练计划。</p><p><br></p><p>&nbsp;&nbsp;在旧时代，健美是仍是一项以“美”为主导的运动。当时的健美运动员肌肉量远不如现在的巨兽，但似乎更符合“健美”的初衷：即使是大重量级选手，像施瓦辛格和卢弗里基诺，身材依旧如古希腊雕塑般匀称、美观。而当今的选手看起来像外星生物一般骇人。</p><p>&nbsp;</p><p>&nbsp;&nbsp;弗兰克赞恩三次在奥赛中夺魁（1977，1978，1979），也是为数不多击败过施瓦辛格的选手。赞恩经常以近乎完美的比例屡屡战胜肌肉量远超他的竞争者。</p><p class="ql-align-center"><br></p><p class="ql-align-center"><span style="background-color: transparent;"><img src="http://www.yaling8.com/uploads/allimg/210426/1-210426164336201.png" alt="弗兰克赞恩击败过施瓦辛格的选手"></span></p><p class="ql-align-center">&nbsp;</p><p>&nbsp;&nbsp;现代健美运动员上台动辄300磅，而赞恩的赛季体重只有不到200磅。比起庞大的肌肉量，他更专注于刻画肌肉细节、调整肌肉比例，力求完美、细致、均衡的身材。</p><p><br></p><p>&nbsp;&nbsp;与大多运动员的增肌减脂循环计划不同的是，弗兰克·赞恩长年保持着较低的体脂，仅仅在赛季对训练及饮食进行微调。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;弗兰克赞恩的增肌计划</strong></p><p>&nbsp;</p><p>&nbsp;&nbsp;施瓦辛格经常与赞恩一同训练，因此前者的训练理念对后者产生了深远的影响。施瓦辛格是高容量、高频率训练的典型代表，他通常采用三分化（推拉腿）计划，一周训练六天。作为搭档，赞恩的增肌计划有着异曲同工之妙。</p><p><br></p><p>&nbsp;&nbsp;作为职业健美选手，训练、休息、恢复是赞恩的日常，而且他拥有最顶尖的饮食把控能力，因此赞恩得以长期采用高容量、高频率的计划。但对于大多数健美爱好者来说，还是需要灵活控制训练量和频率方能长久(如果你想借鉴赞恩的计划，强烈建议将总的训练组数减半，避免训练过度)。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;赞恩的训练基本分化如下：</strong></p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周一：背、二头、前臂、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周二：休息</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周三：腿、小腿、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周四：休息</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周五：胸、肩、三头、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周六：背、二头、前臂、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周日：休息</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周一：腿、小腿、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周二：休息</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周三：胸、肩、三头、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>周四：背、二头、前臂、腹</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;&nbsp;</strong>——循环——</p><p>&nbsp;</p><p>&nbsp;</p><p><strong style="background-color: transparent;">赞恩习惯在练腿日前后设置休息日，原因有二：</strong></p><p>&nbsp;</p><p>一.确保深蹲时背部状态新鲜，因此背和腿之间必须休息一天。</p><p>二.繁重的腿部训练对中枢神经压力很大，需要在前后各安排一整天的休息才能完全恢复。</p>','/api/upload/1601838192338665472.jpg',null);
insert into `article` values ('4','健身里6个超烂坏习惯，效果堪比自残！','健身','610','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>锻炼身体可以让我们体态变理想、运动能力变好，绝对是一件有益身心的事情，但是若没有保持良好的观念与习惯，很容易反过来伤害自己的身体。</p><p><br></p><p>以下6个超烂的坏习惯是我们在平常训练中常见的，只会越练越毁身体！看你中了几个？</p><p><br></p><p>01</p><p>带着疼痛训练</p><p><br></p><p>这是许多热爱运动和训练的人常见的问题，因为错误的观念而推崇"No Pain, No Gain"的价值观，但对于身体来说，疼痛是一个重要的信号，他正在告诉我们身体有某些地方出了问题，若你忽略疼痛而持续训练，只会将信号转变为真实的伤害。</p><p><br></p><p>所以如果你做任何动作感觉到疼痛，请先停止这个动作，找专业教练查看问题的根源，找到解决的方法，千万别带着无所谓或者硬汉心态去健身！</p><p><br></p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p>02</p><p>忽略休息的重要性</p><p><br></p><p>许多人几乎天天都安排做各式各样的运动，健身房团课、跑步等等，通常都是害怕一天的不训练，会影响自己达成目标的效果，其实正好相反，这样子不让身体有休息机会的方式，反而会让自己离目标越来越遥远，这也是大多数人没想到的运动伤害来源－过度使用。</p><p><br></p><p>要记得，身体实际上并不是在训练中进步的，而是在训练后的休息中，去调节生理压力与修复损伤来获得进步的，因此适当的安排穿插休息日，可以让你的进步更明显，是非常重要的一件事。</p><p><br></p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p>03</p><p>只做自己喜爱的训练</p><p><br></p><p>或者说训练内容太过单调，缺乏变化性。</p><p><br></p><p>当身体一直面对同样的刺激的时候，他所产生的适应就会越来越不明显，不管你做的再认真努力，你都无法再看见明显的进步，还会导致身体的平衡性被破坏，比如过多的练胸，缺乏背部的练习，导致圆肩体态问题。所以在整个健身计划中，应当每隔一段时间就安排不同的训练元素进去，让身体因再度被挑战而进步。</p><p><br></p><p><img src="data:image/jpeg;base64,"></p><p>04</p><p>身体缺乏控制性</p><p><br></p><p>不论是哪一种类型的训练，只要你处于训练之中，就应该尽可能地去控制你的身体，这绝对是远离运动伤害很重要的一点。经常看见许多人在运动时，身体几乎没有支撑稳定性，节奏也忽快忽慢，每一个动作都令人担忧。</p><p><br></p><p>通常出现这种问题的原因有「疲劳」、「技术不熟」或是更直接的「失去专注力」，要记得一旦我们动作失去控制性，即使是像坐式脚踏车那样公认安全性极高的训练，都会因此而得到伤害。</p><p><br></p><p><br></p><p><br></p><p>05</p><p>使用不正确的动作训练</p><p><br></p><p>在阻力训练中，不熟悉错误的动作技术会让关节处在不良的力学下，如此便会大幅提高训练伤害风险，当然也包含了本身就充满风险的训练动作。</p><p><br></p><p>再来就是每个人身体的条件不尽相同，有肢体长度、体重、关节活动度等等众多差异组成，若忽视动作原则一昧模仿他人，也有可能带来问题，这就像拿身体来赌博一样，应该不是一件好事。</p><p><br></p><p><br></p><p><br></p><p>06</p><p>高估自己的进步</p><p><br></p><p>我必须老实说这件事极大部分发生在男性身上，因为旁人的眼光与对自我的期待与信心，往往会在很短的时间内，大比例的增加训练的强度，这样会让他们觉得自己”真的变强壮”了。</p><p><br></p><p>而实际上并没有，因为身体要通过适应、修复的过程才能让他有实际的进步，但当我们一次增加了太多的压力与损伤时，身体的适应反应无法负担，带来伤害只是时间的问题而已，所以千万记得要让自己训练强度的增加逐步上升。</p><p><br></p><p>一般会建议每个阶段的强度增加控制在8% 的 ± 2%左右即可，而且当程度越往上提升，这个%将会越小。</p><p><br></p><p><br></p><p>以上就是训练常见的坏习惯，</p><p>希望能对大家有所帮助，</p><p>让我们一起用心运动爱自己吧</p>','/api/upload/1597804746763141120.jpg',null);
insert into `article` values ('5','全人类前1%的力量水平','健身','499','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>何定义一个人强悍与否？通过分析多个颇具权威的自然力量举比赛数据，我总结出了一套评判一个人强壮程度的标准。</p><p>&nbsp;</p><p>&nbsp;&nbsp;过去的50年里，人体潜力的开发程度越来越高，各路巨兽层出不穷，创造和刷新了许多令人目瞪口呆的记录。你肯定在社交媒体上看过诸如魔山硬拉501公斤、Eric Spoto卧推将近800磅的视频——他们的力量水平和我等凡人简直是云泥之别。但是我们不应该就这样妄自菲薄，让我来带你分析一下：</p><p class="ql-align-center"><br></p><p class="ql-align-center"><span style="background-color: transparent;"><img src="http://www.yaling8.com/uploads/allimg/210621/1-2106211641092I.png" alt="全人类前1%的力量水平"></span></p><p class="ql-align-center">&nbsp;</p><p>&nbsp;&nbsp;1000+磅的深蹲/硬拉，800磅的卧推是如何完成的？</p><p><br></p><p>&nbsp;&nbsp;除了他们超然的天赋以及非人的训练强度之外，还有两个不可忽视的因素：</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;1. 高科技装备</strong></p><p>&nbsp;</p><p>&nbsp;&nbsp;随着现代科学的进步，科学家们发明出了许多能够帮助运动员大幅提升运动表现的黑科技装备，例如游泳运动员的鲨鱼皮泳衣，马拉松运动员们的超轻量化跑鞋等。对于举重/力量举来说，特制的深蹲套装和卧推服能够大幅提高运动员的力量表现。</p><p class="ql-align-center"><br></p><p class="ql-align-center"><br></p><p class="ql-align-center">&nbsp;</p><p>&nbsp;&nbsp;如果一个全副武装的运动员能够卧推800磅的话，那么大概率在没有装备加持的情况下只能推起500磅。同样的道理，无装备深蹲700磅是十分罕见的，但是穿上深蹲服、搭配着深蹲紧身裤和绑膝之后，运动员们得以深蹲超过1000磅的重量。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;2. 药物加持</strong></p><p>&nbsp;</p><p>&nbsp;&nbsp;第二个因素便是老生常谈了——类固醇以及生长激素的应用。别误解我的意思，我并不是说所有大力士都是药罐子，事实上许多自然运动员都拥有令人惊叹的力量水平。我仅仅是站在科普的角度告诉大家，在力量举这项运动中，药物的使用实际上非常普遍。</p><p>&nbsp;</p><p>&nbsp;&nbsp;我热爱这项运动，也尊重所有在梦想的道路上一往无前的运动员们。</p><p>&nbsp;</p><p>&nbsp;&nbsp;这篇文章的意义在于为“没有科技加持”的普通爱好者提供一份可靠的力量评判标准。</p><p>&nbsp;</p><p><strong style="background-color: transparent;">&nbsp;&nbsp;总结:爱好者并不需要按照竞技运动员的标准来要求自己。如果你懒得看前面的表格，那么这里我提供一组更精简的数据供大家参考。</strong></p><p><br></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;达成如下的力量水平将让你轻松实现“力型兼备”。</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;·卧推300磅</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;·深蹲400磅</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;·硬拉500磅</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;·高翻225磅</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;·站姿推举225磅</strong></p><p><strong style="background-color: transparent;">&nbsp;&nbsp;·杠铃划船300磅</strong></p><p>&nbsp;</p><p>&nbsp;&nbsp;1200磅的总成绩（卧推+深蹲+硬拉）是95%的爱好者永远无法企及的高度。而1500磅的总成绩已经足以让你在普通自然力量举比赛中所向披靡。</p>','/api/upload/1601837910749872128.jpg',null);
insert into `article` values ('6','健身必练的10个动作，每一个都无可替代！','健身','211','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>一般一个部位可以有很多个动作训练到，但以下挑选的10个黄金动作，建议你一定要安排到你的日常训练计划中，因为它们真的无可替代！</p><p><br></p><p>图片</p><p><br></p><p>一、深蹲</p><p><br></p><p><br></p><p>锻炼腿部、臀部肌肉的王牌动作，而同时还调动了多部分肌肉发力，对减脂同样有效果。这里所说的深蹲并不局限于在健身房做杠铃负重深蹲，你也可以选择徒手深蹲等。</p><p><br></p><p>二、硬拉</p><p><br></p><p><br></p><p>硬拉可以说与深蹲匹敌，不仅轰炸你的背部，强化核心肌肉，训练时产生的雄激素量最大，也是其它训练动作都无法相比的。雄激素可以创造一个有利于肌肉生长的环境，从而提高上半身和下半身的力量。当然它也可以促进你的性欲。</p><p><br></p><p>三、卧推</p><p><br></p><p><br></p><p>可以说几乎所有的健身初学者都是从卧推这个动作开始，卧推也是上半身力量训练最基础的 动作之一。要想练出有型的胸肌，用卧推这个动作绝对杠杠滴。</p><p><br></p><p>四、推举</p><p><br></p><p><br></p><p>三角肌锻炼基本动作，常采用大重量，对三角肌中束刺激极大。想要练出有型的肩膀，推举可以说是最好的动作。</p><p><br></p><p>练习者背部挺直坐于长凳上，正手抓握哑铃举至双肩两侧，掌心向前。动作过程中吸气，垂直向上推举哑铃，动作完成时呼气，重复。可以采用坐姿或站姿进行练习。</p><p><br></p><p>五、俯身划船</p><p><br></p><p><br></p><p>杠铃划船这个动作一般都采用宽握距，也就是比肩宽略微宽一点，主要锻炼背阔肌上部，同时会练到大圆肌，还有三角肌后束，以及斜方肌。</p><p><br></p><p>练习时双手略比肩宽持杠铃，俯身保持腰背部挺直，杠铃自然下垂至膝盖以下，肩胛完全放松，保持膝盖微微弯曲。动作过程中集中背部肌群的力量，将杠铃沿着大腿提拉至下腹，动作终点稍停，然后再用背部肌群的力量控制着慢慢还原至起始位置，重复练习即可。</p><p><br></p><p>六、引体向上</p><p><br></p><p><br></p><p>背部锻炼最基础，也是最方便的动作。自重引体做不到之时，不妨先从借力开始。两手用宽握距正握（掌心向前）单杠，略宽于肩，两脚离地，两臂自然下垂伸直。</p><p>用背阔肌的收缩力量将身体往上拉起，当下巴超过单杠时稍作停顿，静止一秒钟，使背阔肌彻底收缩。然后逐渐放松背阔肌，让身体徐徐下降，直到回复完全下垂，重复再做。可以弯曲膝关节、将两小腿向后交叉，使身体略微后倾，能更好地锻炼背部肌肉。</p><p><br></p><p>七、弯举</p><p><br></p><p><br></p><p><br></p><p>其实训练二头也就这么一个动作了吧…弯举的方法可真是千变万化，锤式，哑铃，杠铃，曲杠，牧师蹬…本质上，也就是从弯举这一个动作中，我们获得了钢铁一样的巨大肱二头肌！</p><p><br></p><p>八、臂屈伸</p><p><br></p><p><br></p><p><br></p><p>双杠臂屈伸以练习胸肌、肱三头肌和三角肌（前束）为主，兼练背阔肌、斜方肌等。需要的器材为双杠最佳。初始练习者力量不佳，可选择长凳、床等生活家具，采取同样动作进行（因脚踩地可减低体重负荷）。</p><p><br></p><p>动作的过程为双手分别握杠，两臂支撑在双杠上，头正挺胸顶肩，躯干、上肢与双杠垂直，屈膝后小腿交叠于两脚的踝关节部位。肘关节慢慢弯屈，同时肩关节伸屈，使身体逐渐下降至最低位置。稍停片刻，两臂用力撑起至还原。</p><p><br></p><p>九、直腿硬拉</p><p><br></p><p><br></p><p>直腿硬拉可以很好的锻炼大腿后侧股后肌群，有句话是这么说的，如果你的大腿后侧不够强壮，那么你也体会不到最大深蹲重量。可见用直腿硬拉加强股后肌群的重要性。</p><p><br></p><p>十、负重提踵</p><p><br></p><p><br></p><p>这个动作是练小腿的，日常训练中虽然练的人不多。但对于全身发展的你，小腿也是不可忽略的一个部位。因为瘦弱的小腿绝对会影响你整个身型。</p>','/api/upload/1597802876418129920.jpg','健身');
insert into `article` values ('7','健身出效果的七大原则！','健身','274','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>很多健身者在健身一段时间之后，会觉得没有太大效果，导致最终放弃训练，其实健身是一门系统科学，不是短时间内就能看到成效，想要健身有效果，就要坚持遵循正确的训练方法和原则。</p><p><br></p><p><br></p><p>一、收腹、收肋、挺胸、沉肩</p><p><br></p><p>健身需要长期坚持才能见到效果，如果在这段时间内训练动作错误，造成身体损伤了才会被察觉出来。健身初学者在做训练动作时应收腹、收肋、挺胸、沉肩，最大限度让动作不变形，以保证动作准确不代偿，才能达到想要的健身训练效果。</p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p><br></p><p>二、用力时呼气，还原时吸气</p><p><br></p><p>在训练时，由于用力时所用的时间比较短，还原时所用的时间比较长，因而采用用力时呼气、还原时吸气的呼吸方法，吸气的时间比较长可使空气经过鼻腔的时间延长，从而减小对肺部的刺激，让身体感觉更舒服。</p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p><br></p><p>三、稳定和控制比重量更重要</p><p><br></p><p>对于健身初学者来说，使用固定器械训练可以快速掌握动作要领并找到肌肉发力的感觉，但是由于固定器械的发力轨迹相对固定，不能平衡身体各肌肉群之间的协同性和稳定性，所以在熟练掌握了固定器械训练模式后，建议还是要多选择杠铃或哑铃的自由重量训练模式，以锻炼身体各肌肉群之间的协同性和稳定性。</p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p><br></p><p>四、训练前后一定记得做热身和拉伸</p><p><br></p><p>运动前的热身相信每个健身者都有做，但运动后的拉伸往往容易被忽视。运动后的拉伸可以降低体温并缓和呼吸，让紧绷的肌肉放松下来，减少疲劳并促进肌肉生长，所以想要维持长期的健身热情，训练后的拉伸步骤必不可少。</p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p><br></p><p>五、不要每天都练相同的部位</p><p><br></p><p>有些健身者的训练计划中，每天只有胸肌、腹肌或者三角肌的训练，这样的做法是错误的。身体是一个整体，不能只练自己喜欢的部位，只有全身性系统的训练，才能让更多的肌肉参与其中，健身效果才会更好。另外，每个肌肉群训练后都需要有恢复时间，更好的休息才能更好的增肌。</p><p><br></p><p><br></p><p><br></p><p>六、先力量训练，再有氧训练</p><p><br></p><p>有氧训练时不只会消耗脂肪，同时还会消耗葡萄糖，而葡萄糖是力量训练的主要能量来源，如果先做有氧训练再做力量训练，肌肉所需的能量得不到保证，不仅训练动作无法发挥到最佳状态，增肌也会大打折扣，因此建议最好先力量训练再有氧训练。</p><p><br></p><p><br></p><p><br></p><p>七、三分练，七分吃，十分睡</p><p><br></p><p>健身三大要素：训练、营养、休息，缺一不可。肌肉总是在身体休息的时候生长，通过有效的训练充分刺激肌肉，然后补充足够的营养和蛋白质，再创造一个良好的睡眠环境，接下来就是等待肌肉纤维的增量修复。</p><p><br></p><p><br></p>','/api/upload/1597803864923308033.jpg',null);
insert into `article` values ('8','亚洲最强悍的手臂居然是这个日本人','健身','30','0','2023-03-06 14:58:07.0','2023-03-06 14:58:07.0',null,null,null,'<p>如果你看过这个日本人的夸张的手臂，一定会被他吸引冲击过！</p><p>&nbsp;</p><p>山岸秀匡</p><p>&nbsp;</p><p>男</p><p>&nbsp;</p><p>日本人</p><p>&nbsp;</p><p>出生于1973年6月30日</p><p>&nbsp;</p><p>身高163厘米（5英尺5英寸）</p><p>&nbsp;</p><p>体重：100公斤</p><p><br></p><p><br></p><p>&nbsp;</p><p>亚洲最强悍的手臂居然是这个日本人</p><p>&nbsp;</p><p>“我会一直注意我手肘的位置，以确保每个动作都能很好的刺激我的二头和手臂的必要刺激部位”</p><p>&nbsp;</p><p>亚洲最强悍的手臂居然是这个日本人</p><p>&nbsp;</p><p>当谈到二头肌训练的，这位日本最著名的健美运动员强调这个关键点。他会精选一些不同的动作，对手臂进行多角度的轰击。</p><p>&nbsp;</p><p>问：你总是用杠铃弯举来开始你的手臂锻炼？</p><p>&nbsp;</p><p>山岸：是的，这个练习可以灵活处理不同重量对二头肌的刺激。我经常会在直杠和曲杠之间交替使用。</p><p><br></p><p><br></p><p>&nbsp;</p><p>问：上斜哑铃弯举不是很多人采用的动作，为什么你会使用它？</p><p>&nbsp;</p><p>山岸：这个动作可以更好的拉伸肱二头肌和肱二头长头肌，但是要非常的注意动作的安全性，防止受伤的危险，不要使用大重量。</p><p>&nbsp;</p><p><br></p><p>&nbsp;</p><p>问：牧师凳是很好的肱二头的短头锻炼，你是如何获得良好的顶峰收缩？</p><p>&nbsp;</p><p>山岸：嗯，我总是利用这个动作更好的享受顶峰收缩的刺激，你需要使用一个你能完全控制的重量，不要盲目追求重量。</p><p>&nbsp;</p><p>问：锤式弯举是否对肱二头肌的发展非常的重要？</p><p>&nbsp;</p><p>山岸：是的。锤式弯举和反向弯举– 我周与周交替更换这个动作–这非常重要，因为他们的目标肱桡肌和肱肌，这会让你的肱二头肌看起来更大。如果你想获得更大的手臂，你需要训练这些肌肉。</p>','/api/upload/1601838430096982016.jpg',null);
